const proof = (facts: Record<string, number>, anchors: Record<string, string>, result: TransferProof['result'], format: TransferProof['format'] = 'number', precision?: number, template?: string): TransferProof => ({ facts, anchors, result, format, ...(precision === undefined ? {} : { precision }), ...(template === undefined ? {} : { template }) });
const fact = (key: string) => ({ fact: key });
const expr = (op: 'add' | 'sub' | 'mul' | 'div' | 'floor' | 'ceil' | 'pow' | 'min' | 'max', ...args: TransferExpression[]): TransferExpression => ({ op, args });
const medianOfFive = (a: string, b: string, c: string, d: string, e: string): TransferExpression => {
  const triplets: string[][] = [[a, b, c], [a, b, d], [a, b, e], [a, c, d], [a, c, e], [a, d, e], [b, c, d], [b, c, e], [b, d, e], [c, d, e]];
  // The maximum of every 3-value subset's minimum is the third-smallest value.
  return expr('max', ...triplets.map(([x, y, z]) => expr('min', fact(x), fact(y), fact(z))));
};
const combinations = (values: string[], count: number): string[][] => count === 0 ? [[]]
  : values.flatMap((value, index) => combinations(values.slice(index + 1), count - 1).map(rest => [value, ...rest]));
const orderStatistic = (keys: string[], rank: number): TransferExpression =>
  expr('max', ...combinations(keys, rank).map(group => expr('min', ...group.map(fact))));
const medianOfSix = (keys: string[]): TransferExpression =>
  expr('div', expr('add', orderStatistic(keys, 3), orderStatistic(keys, 4)), 2);
const simultaneousEventsInWindow = (a: string, b: string, gcd: number, originMinute: number, lower: string, upper: string): TransferExpression => {
  const period = expr('div', expr('mul', fact(a), fact(b)), gcd);
  const lowerOffsetMinusOne = expr('sub', expr('sub', fact(lower), originMinute), 1);
  const upperOffset = expr('sub', fact(upper), originMinute);
  return expr('sub', expr('floor', expr('div', upperOffset, period)), expr('floor', expr('div', lowerOffsetMinusOne, period)));
};

