function makeContent(r: ArithmeticRecipe, source: Question) {
  return {
    text: r.text, numbers: [...r.numbers], answer: r.answer,
    answerSentence: `答案是${r.answer}${r.unit}。`, equation: r.equation,
    explanation: r.explanation, solutionSteps: [...r.steps], hints: [...r.hints],
    ...(source.answerSchema?.kind === 'text'
      ? { answerSchema: { kind: 'text' as const, acceptedAnswers: [String(r.answer)] } }
      : source.answerSchema ? { answerSchema: structuredClone(source.answerSchema) } : {}),
  };
}

