/** Fixed, source-bound progression variants. No parameter is inferred from operation labels. */
export function buildProgressionTransfers(sources: readonly Question[]): TransferBatch {
  const byId = new Map(sources.map((question) => [question.id, question]));
  const arithmeticEntries = recipes.flatMap((r) => {
    const source = byId.get(r.id);
    if (!source) return [];
    const witness = { kind: 'arithmetic' as const, source: r.sourceProof, variant: r.variantProof };
    return [makeTransferEntry(source, makeContent(r, source), relationFor(r), witness, 'numeric-distinct')];
  });
  const enumerationEntries = enumRecipes.flatMap((r) => {
    const source = byId.get(r.id);
    if (!source) return [];
    const witness: TransferWitness = { kind: 'enumeration', model: r.model, source: r.source, variant: r.variant };
    const variant = makeTransferEntry(source, {
      text: r.text, numbers: [...r.numbers], answer: r.answer, answerSentence: r.answerSentence,
      equation: r.equation, explanation: r.explanation, solutionSteps: [...r.steps], hints: [...r.hints],
      ...(r.answerSchema ? { answerSchema: structuredClone(r.answerSchema) } : source.answerSchema ? { answerSchema: structuredClone(source.answerSchema) } : {}),
    }, {
      family: r.family, targetRole: r.target, roles: r.roles, operations: ['finite-enumeration'],
      units: ['integers', 'count'], invariants: r.invariants,
    }, witness, r.mode ?? 'numeric-distinct');
    return [variant];
  });
  const recipeIds = new Set([...recipes.map((r) => r.id), ...enumRecipes.map((r) => r.id)]);
  const gaps = sources.filter((source) => source.id.startsWith('prog_') && !recipeIds.has(source.id)).map((source) => {
    const gap = remainingGaps[source.id];
    if (!gap) throw new Error(`Progression gap ${source.id} has no reviewed mathematical reason`);
    return { sourceId: source.id, ...gap };
  });
  return { entries: [...arithmeticEntries, ...enumerationEntries], gaps };
}
